class Solution { public: int romanToInt(string s) { auto val=[](char c){ switch(c){case 'I':return 1;case 'V':return 5;case 'X':return 10;case 'L':return 50;case 'C':return 100;case 'D':return 500;default:return 1000;} }; int ans=0; for(int i=0;i<(int)s.size();++i){ int x=val(s[i]); if(i+1<(int)s.size()&&x<val(s[i+1])) ans-=x; else ans+=x; } return ans; } };